source='''def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        pos = {c: x for c, x in enumerate(row) if x}
        pairs = [(4, 7), (7, 4), (1, 8), (8, 1)]
        for a, b in pairs:
            for ca, xa in pos.items():
                for cb, xb in pos.items():
                    if xa == a and xb == b and abs(ca-cb) > 1:
                        # The outer/right object moves one cell toward its partner.
                        if (a, b) in [(4, 7), (1, 8)] and ca > cb:
                            out[r][ca] = 0
                            out[r][ca-1] = a
                        elif (a, b) in [(7, 4), (8, 1)] and ca > cb:
                            out[r][ca] = 0
                            out[r][ca-1] = a
    return out
'''
# Simpler validated implementation: rightmost relevant partner moves one step left.
source='''def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        colored = [(c, x) for c, x in enumerate(row) if x]
        for i, (ca, a) in enumerate(colored):
            for cb, b in colored[i+1:]:
                if (a, b) in ((4, 7), (1, 8)):
                    out[r][cb] = 0
                    out[r][cb-1] = b
                elif (a, b) in ((7, 4), (8, 1)):
                    out[r][cb] = 0
                    out[r][cb-1] = b
    return out
'''
